-- Pseudo-minting: a picture is a stack of layers (background, skin, outfit, expression, eyes, accessory,
-- headwear). Minting rolls one option per layer, weighted by rarity, and saves only the result in
-- KillTrackerDB.mints = { { number, traits = { [layer key] = option id }, time, claim } }. Pictures are
-- drawn by stacking the chosen layer images; a backend can rebuild the same picture from the traits.
--
-- Art: the options and their textures come from MintArt.lua, generated by tools/convert-art.js from the
-- PNGs in tools/art-source. Options with perSkin have one texture per skin (eyes and mouths drawn in
-- the skin's colour), picked by the picture's skin trait.

local _, ns = ...

-- The price of a mint is a guild setting (Config.lua); each picture remembers what it cost.
-- A picture's price: the guild's setting, less your rank's discount (Ranks.lua); and POT_PRICE_STEP of that more for
-- each ingredient in the minting pot (tokens: { [ingredient key] = n }, MintPot.lua; fuels too).
local POT_PRICE_STEP = 0.1
function ns.MintCost(tokens)
    local discount = ns.RankPerk and ns.RankPerk("discount") or 0
    local count = 0
    for _, n in pairs(tokens or {}) do count = count + n end
    return math.max(1, math.floor(ns.Config("mintCost") * (1 - discount) * (1 + count * POT_PRICE_STEP) + 0.5))
end

-- Four rarities; there is no common (uncommon is the everyday tier).
local RARITY_WEIGHTS = { uncommon = 25, rare = 10, epic = 4, legendary = 1 }
ns.MINT_WEIGHTS = RARITY_WEIGHTS
local RARITY_SCORE = { uncommon = 1, rare = 2, epic = 3, legendary = 4 }
ns.MINT_SCORES = RARITY_SCORE
local RARITY_ORDER = { "uncommon", "rare", "epic", "legendary" }
-- A picture's overall rarity: the share of all rolls that score at least as high (see ns.MintRarity).
local PICTURE_TIERS = { { "legendary", 0.015 }, { "epic", 0.05 }, { "rare", 0.17 } }  -- the rest: uncommon
ns.MINT_TIERS = PICTURE_TIERS  -- (these settings are read by the SOLC Puzzle Discord Activity's art build too)

-- Layers from back to front; options { id (never change once released), name, rarity, texture, rect,
-- perSkin } from MintArt.lua. rect = { x, y, width, height } as fractions of the picture places a
-- cropped image; options without one cover the whole picture. Layers without art are left out.
ns.MintLayers = {}
for _, layer in ipairs({
    { key = "background", name = "Background" },
    { key = "skin", name = "Skin" },
    { key = "outfit", name = "Outfit" },
    { key = "expression", name = "Expression" },
    { key = "eyes", name = "Eyes" },
    { key = "accessory", name = "Accessory" },
    { key = "headwear", name = "Headwear" },
}) do
    layer.options = ns.MintArt and ns.MintArt[layer.key] or {}
    for _, option in ipairs(layer.options) do option.layerKey = layer.key end  -- (an unlockable's own unlock key)
    if #layer.options > 0 then ns.MintLayers[#ns.MintLayers + 1] = layer end
end

-- Unlockable options (option.unlock, Unlocks.lua: a dungeon's backdrop, a boss's skin or gear, an epic's layer) are
-- only rolled once you've unlocked them, and left out of the odds that grade a picture's rarity (so adding them never
-- changes the rarity of pictures already minted).
function ns.MintAllowed(option)
    if option.retired then return false end  -- (shown on the pictures that have it, never rolled again: MintArt.lua)
    return not option.unlock or (ns.IsUnlocked ~= nil and ns.IsUnlocked((option.layerKey or "") .. ":" .. option.id))
end

-- The skin whose per-skin art (eyes, mouths) a picture's skin wears: its own, or for a boss skin the skin it's drawn
-- on (option.faceSkin).
local skinFaces
function ns.FaceSkin(skin)
    if not skinFaces then
        skinFaces = {}
        for _, option in ipairs(ns.MintArt and ns.MintArt.skin or {}) do
            if option.faceSkin then skinFaces[option.id] = option.faceSkin end
        end
    end
    return skinFaces[skin] or skin
end

-- The texture path of an option in a picture with these traits; edition ("crayon", "sketch"): its twin in that
-- edition, if it has one.
function ns.MintTexture(option, traits, edition)
    local texture = edition and option[edition] or option.texture
    if option.perSkin then return texture:format(ns.FaceSkin(traits.skin) or "") end
    return texture
end

-- The editions: every picture layer has twins in other styles (MintArt.lua, from tools/convert-art.js): crayon
-- (hand-drawn) and sketch (the painting through a crayon filter). Unlocked for a picture for now by minting it yourself
-- (mint.crayon; more ways to unlock later). Its owner picks each layer's edition: mint.style = an edition (every layer
-- in it), a table { [layer key] = edition } (a mix: a crayon frog on a painted ogre), or nil (painted). Synced, so
-- guildmates see it that way too.
ns.EDITIONS = { "crayon", "sketch" }
ns.EDITION_NAMES = { crayon = "crayon", sketch = "sketch" }
local EDITION_CODES = { crayon = "c", sketch = "s" }
local EDITION_FROM_CODE = { c = "crayon", s = "sketch" }
function ns.MintStyle(mint) return mint and mint.style or nil end
function ns.CrayonUnlocked(mint) return mint and mint.crayon == true end  -- (unlocks every edition, for now)
-- A layer's edition in this style, or nil (painted).
function ns.LayerEdition(style, layerKey)
    if type(style) == "table" then return style[layerKey] end
    return style
end
-- The style as text, for syncing and comparing: "" painted, "c" / "s" every layer in that edition, "skin=c,hat=s" a mix.
function ns.StyleKey(style)
    if not style then return "" end
    if type(style) ~= "table" then return EDITION_CODES[style] or "" end
    local parts = {}
    for key, edition in pairs(style) do parts[#parts + 1] = key .. "=" .. (EDITION_CODES[edition] or "c") end
    table.sort(parts)
    return table.concat(parts, ",")
end
function ns.StyleFromKey(text)
    if not text or text == "" then return nil end
    if EDITION_FROM_CODE[text] then return EDITION_FROM_CODE[text] end
    local style, any = {}, false
    for key, code in text:gmatch("([%w_]+)=(%a)") do
        if EDITION_FROM_CODE[code] then style[key], any = EDITION_FROM_CODE[code], true end
    end
    return any and style or nil
end
function ns.SetMintStyle(mint, style)
    if style and not ns.CrayonUnlocked(mint) then return end
    mint.style = style
    ns.Touch(mint)  -- syncs it
    if ns.OnKillsChanged then ns.OnKillsChanged() end
end
-- One layer in an edition (or painted: nil); the style kept as simple as it can be.
function ns.SetLayerEdition(mint, layerKey, edition)
    if not ns.CrayonUnlocked(mint) then return end
    local style, first, same, any = {}, nil, true, false
    for _, layer in ipairs(ns.MintLayers) do
        local e = edition  -- (not "x and edition or y": edition is nil for painted)
        if layer.key ~= layerKey then e = ns.LayerEdition(mint.style, layer.key) end
        if mint.traits[layer.key] then
            style[layer.key] = e
            if e then any = true end
            if first == nil then first = e or false elseif (e or false) ~= first then same = false end
        end
    end
    if not any then ns.SetMintStyle(mint, nil)
    elseif same then ns.SetMintStyle(mint, first)
    else ns.SetMintStyle(mint, style) end
end
-- The edition after this one: painted, crayon, sketch, painted...
function ns.NextEdition(edition)
    if not edition then return ns.EDITIONS[1] end
    for i, e in ipairs(ns.EDITIONS) do if e == edition then return ns.EDITIONS[i + 1] end end
end
-- A picture drawn on canvas in its owner's chosen style, redrawn only when its traits or style changed.
function ns.DrawMint(canvas, mint, tilt)
    local style = ns.MintStyle(mint)
    local key = ns.StyleKey(style)
    if canvas.drawnTraits == mint.traits and canvas.drawnStyle == key and canvas.drawnTilt == tilt then return end
    ns.RenderMint(canvas, mint.traits, tilt, style)
    canvas.drawnTraits, canvas.drawnStyle, canvas.drawnTilt = mint.traits, key, tilt
end

local function FindOption(layer, id)
    for _, option in ipairs(layer.options) do
        if option.id == id then return option end
    end
end

-- Your rank's luck while you mint (Ranks.lua): epic and legendary options weigh this much more. 1 otherwise (an
-- officer's mint battle rolls without it).
local luck = 1
local LUCKY = { epic = true, legendary = true }
-- boost (optional): the pot's rarity boost on this layer ({ [rarity] = this much more weight }).
local function Weight(option, boost)
    local weight = option.weight or RARITY_WEIGHTS[option.rarity]
    if LUCKY[option.rarity] then weight = weight * luck end
    if boost and boost[option.rarity] then weight = weight * boost[option.rarity] end
    return weight
end

-- The minting pot (MintPot.lua; its ingredients, Unlocks.lua): what's thrown in while a mint rolls, { [ingredient] = n }.
-- - dungeon ingredients make each layer likelier to roll from those dungeons' pieces you've unlocked (a dungeon picked by
--   its share of them);
-- - a layer's ingredient (ns.LAYER_INGREDIENTS) aims at that layer: it counts POT_LAYER_POWER times there, so a dungeon's
--   plus a layer's point at one piece; and it makes that layer's own rolls rarer;
-- - fuels in the fire under it (ns.FUELS, at most FIRE_SLOTS) make their rarity and up likelier (on the layers aimed
--   at, or every layer if none is): Frostwood rare and up, Shimmer Dust epic and up, Sunwood legendary.
-- A layer's chance to roll from the pot climbs by less with each ingredient and never gets past POT_CEILING, however
-- full the pot (how much fits in it: your cauldron's slots, Ranks.lua): it skews, it never guarantees.
local POT_CEILING, POT_DECAY, POT_LAYER_POWER = 0.6, 0.85, 2
local RARITY_STEP, RARITY_MAX, LAYER_RARITY = 0.25, 3, 0.5
local FIRE_SLOTS = 3
ns.POT_CEILING, ns.FIRE_SLOTS = POT_CEILING, FIRE_SLOTS
-- A layer's chance to roll from the pot, for this much pull on it.
local function Pull(power) return power > 0 and POT_CEILING * (1 - POT_DECAY ^ power) or 0 end
-- What a pot does to each layer: { [layer key] = { chance (from the pot), dungeons = { [key] = n } (those with a piece
-- for it), total (of those), boost ({ [rarity] = it weighs this much more }), boosted (any of it more than 1) } }.
function ns.PotPlan(ingredients)
    ingredients = ingredients or {}
    local aimed, fire = false, { rare = 0, epic = 0, legendary = 0 }
    for _, fuel in ipairs(ns.FUELS or {}) do fire[fuel.rarity] = fire[fuel.rarity] + (ingredients[fuel.key] or 0) end
    fire.epic = fire.epic + fire.rare
    fire.legendary = fire.legendary + fire.epic  -- (each fuel: its rarity and up)
    for _, layer in ipairs(ns.MintLayers) do
        if (ingredients["l_" .. layer.key] or 0) > 0 then aimed = true end
    end
    local plan = {}
    for _, layer in ipairs(ns.MintLayers) do
        local aim = ingredients["l_" .. layer.key] or 0
        local dungeons, total = {}, 0
        for key, n in pairs(ingredients) do
            if n > 0 and ns.IngredientKind and ns.IngredientKind(key) == "dungeon" then
                for _, option in ipairs(layer.options) do
                    if option.unlock == "clear:" .. key and ns.MintAllowed(option) then
                        dungeons[key], total = n, total + n
                        break
                    end
                end
            end
        end
        local fed = not aimed or aim > 0
        local boost, boosted = {}, false
        for _, rarity in ipairs({ "rare", "epic", "legendary" }) do
            boost[rarity] = math.min(RARITY_MAX, 1 + ((fed and fire[rarity] or 0) + aim * LAYER_RARITY) * RARITY_STEP)
            if boost[rarity] > 1 then boosted = true end
        end
        local chance = total > 0 and Pull(total + aim * POT_LAYER_POWER) or 0
        if chance > 0 then
            -- The pot's pieces can roll the usual way too: keep the likeliest of them, both ways together, at the ceiling.
            local all, top = 0, 0
            for _, option in ipairs(layer.options) do
                if ns.MintAllowed(option) then
                    local weight = Weight(option, boost)
                    all = all + weight
                    local dungeon = option.unlock and option.unlock:match("^clear:(.+)")
                    if dungeon and dungeons[dungeon] then top = math.max(top, weight) end
                end
            end
            local base = all > 0 and top / all or 0
            chance = math.max(0, math.min(chance, (POT_CEILING - base) / (1 - base)))
        end
        plan[layer.key] = { chance = chance, dungeons = dungeons, total = total, boost = boost, boosted = boosted }
    end
    return plan
end
local function FromPot(layer, entry)
    if entry.total <= 0 or math.random() >= entry.chance then return end
    local pick, chosen = math.random() * entry.total, nil
    for key, n in pairs(entry.dungeons) do
        pick = pick - n
        if not chosen and pick <= 0 then chosen = key end
    end
    chosen = chosen or next(entry.dungeons)
    local list, sum = {}, 0
    for _, option in ipairs(layer.options) do
        if option.unlock == "clear:" .. chosen and ns.MintAllowed(option) then
            list[#list + 1] = option
            sum = sum + Weight(option, entry.boost)
        end
    end
    local at = math.random() * sum
    for _, option in ipairs(list) do
        at = at - Weight(option, entry.boost)
        if at <= 0 then return option end
    end
    return list[#list]
end
-- Each option's chance to roll on a layer with this pot (ns.PotPlan's entry for it; nil: as usual): { [option] = chance }.
function ns.LayerOdds(layer, entry)
    local odds, boost = {}, entry and entry.boost
    local total = 0
    for _, option in ipairs(layer.options) do
        if ns.MintAllowed(option) then total = total + Weight(option, boost) end
    end
    local fromPot = entry and entry.total > 0 and entry.chance or 0
    for _, option in ipairs(layer.options) do
        if ns.MintAllowed(option) then
            local p = (1 - fromPot) * Weight(option, boost) / total
            local dungeon = option.unlock and option.unlock:match("^clear:(.+)")
            local n = dungeon and entry and entry.dungeons[dungeon]
            if n and fromPot > 0 then
                local sum = 0
                for _, other in ipairs(layer.options) do
                    if other.unlock == option.unlock and ns.MintAllowed(other) then sum = sum + Weight(other, boost) end
                end
                p = p + fromPot * n / entry.total * Weight(option, boost) / sum
            end
            odds[option] = p
        end
    end
    return odds
end

local plan
local function Roll(layer)
    local entry = plan and plan[layer.key]
    local potted = entry and FromPot(layer, entry)
    if potted then return potted end
    local boost = entry and entry.boost
    local total, last = 0, nil
    for _, option in ipairs(layer.options) do
        if ns.MintAllowed(option) then total, last = total + Weight(option, boost), option end
    end
    local pick = math.random() * total
    for _, option in ipairs(layer.options) do
        if ns.MintAllowed(option) then
            pick = pick - Weight(option, boost)
            if pick <= 0 then return option end
        end
    end
    return last
end

local function TraitKey(traits)
    local parts = {}
    for i, layer in ipairs(ns.MintLayers) do parts[i] = traits[layer.key] or "" end
    return table.concat(parts, "/")
end

-- Weighted pick among every combination not in owned (only used when random rolls keep hitting owned ones).
local function PickUnowned(owned)
    local combos, total = {}, 0
    local function Walk(i, traits, weight)
        local layer = ns.MintLayers[i]
        if not layer then
            if not owned[TraitKey(traits)] then
                local copy = {}
                for k, v in pairs(traits) do copy[k] = v end
                combos[#combos + 1] = { traits = copy, weight = weight }
                total = total + weight
            end
            return
        end
        for _, option in ipairs(layer.options) do
            if ns.MintAllowed(option) then
                traits[layer.key] = option.id
                Walk(i + 1, traits, weight * (option.weight or RARITY_WEIGHTS[option.rarity]))
            end
        end
    end
    Walk(1, {}, 1)
    local pick = math.random() * total
    for _, combo in ipairs(combos) do
        pick = pick - combo.weight
        if pick <= 0 then return combo.traits end
    end
    return combos[#combos].traits
end

-- Chance that a roll scores at least s, for every possible score s (worked out once from the weights).
local atLeast
local function ScoreOdds()
    if atLeast then return atLeast end
    local chance = { [0] = 1 }  -- [score] = chance of exactly that score so far
    for _, layer in ipairs(ns.MintLayers) do
        local total = 0
        for _, option in ipairs(layer.options) do
            if not option.unlock and not option.retired then total = total + (option.weight or RARITY_WEIGHTS[option.rarity]) end
        end
        local nextChance = {}
        for score, p in pairs(chance) do
            for _, option in ipairs(layer.options) do
                if not option.unlock and not option.retired then  -- (the everyday options only, see ns.MintAllowed)
                    local s = score + RARITY_SCORE[option.rarity]
                    nextChance[s] = (nextChance[s] or 0) + p * (option.weight or RARITY_WEIGHTS[option.rarity]) / total
                end
            end
        end
        chance = nextChance
    end
    local maxScore = 0
    for score in pairs(chance) do maxScore = math.max(maxScore, score) end
    atLeast = {}
    local sum = 0
    for score = maxScore, 0, -1 do
        sum = sum + (chance[score] or 0)
        atLeast[score] = sum
    end
    return atLeast
end

-- Overall rarity from the traits' rarities added up, graded by how few rolls score that high:
-- legendary = top 1.5% of pictures, epic = top 5%, rare = top 17%, else uncommon.
function ns.MintRarity(traits)
    local score = 0
    for _, layer in ipairs(ns.MintLayers) do
        local option = FindOption(layer, traits[layer.key])
        score = score + (option and RARITY_SCORE[option.rarity] or 0)
    end
    local share = ScoreOdds()[score] or 1
    for _, tier in ipairs(PICTURE_TIERS) do
        if share <= tier[2] + 1e-9 then return tier[1] end
    end
    return RARITY_ORDER[1]
end

-- The layers hidden under a piece (option.covers: a mask over the mouth): { [layer key] = the piece }. Still rolled and
-- kept, only not drawn: take the piece off (your built ogre) and they're back.
function ns.CoveredLayers(traits)
    local covered = {}
    for _, layer in ipairs(ns.MintLayers) do
        local option = FindOption(layer, traits[layer.key])
        if option and option.covers then
            for key in pairs(option.covers) do covered[key] = option end
        end
    end
    return covered
end

-- Traits as display lines: { { layer name, option name, rarity, layer key, note } } (note: "hidden by ..." under a piece
-- covering it, else nil).
function ns.MintTraits(traits)
    local lines = {}
    local covered = ns.CoveredLayers(traits)
    for _, layer in ipairs(ns.MintLayers) do
        local option = FindOption(layer, traits[layer.key])
        if option then
            local note = covered[layer.key] and ("hidden by " .. covered[layer.key].name) or nil
            lines[#lines + 1] = { layer.name, option.name, option.rarity, layer.key, note }
        end
    end
    return lines
end
-- A trait's note, ready to append to its line (dimmed), or "".
function ns.TraitNote(trait) return trait[5] and ("  |cff8a8a8a(%s)|r"):format(trait[5]) or "" end

-- Rolls and saves a new picture you don't own yet. Returns the mint, or nil and why not.
-- Guild registry: every picture owned by you or a synced friend, as [trait key] = { owner, time }.
-- Owner is nil for your own. Minting never rolls a taken picture.
local function TakenPictures(exceptMint)
    local taken = {}
    for _, mint in ipairs(KillTrackerDB.mints) do
        if mint ~= exceptMint then taken[TraitKey(mint.traits)] = { time = mint.time } end
    end
    for fullName, friend in pairs(KillTrackerFriends or {}) do
        for _, mint in pairs(friend.mints or {}) do
            local key = TraitKey(mint.traits)
            if not taken[key] then taken[key] = { owner = fullName, time = mint.time } end
        end
    end
    return taken
end

-- Rolls a picture nobody in the registry has. Returns traits, or nil if every picture is taken.
local function RollFree(taken)
    local count, possible = 0, 1
    for _ in pairs(taken) do count = count + 1 end
    for _, layer in ipairs(ns.MintLayers) do
        local allowed = 0
        for _, option in ipairs(layer.options) do if ns.MintAllowed(option) then allowed = allowed + 1 end end
        possible = possible * allowed
    end
    if count >= possible then return end
    for _ = 1, 200 do
        local traits = {}
        for _, layer in ipairs(ns.MintLayers) do traits[layer.key] = Roll(layer).id end
        if not taken[TraitKey(traits)] then return traits end
    end
    -- Few pictures left to find (often rare ones): pick among the remaining ones, still by weight.
    -- Only feasible for small sets; with millions of combinations 200 misses in a row won't happen.
    if possible <= 100000 then return PickUnowned(taken) end
end

-- Rolls and saves a new picture nobody in your guild owns yet. Returns the mint, or nil and why not.
-- tokens (optional): the ingredients thrown into the pot, { [ingredient key] = n }; spent with the mint.
function ns.Mint(tokens)
    local db = KillTrackerDB
    local balance, cost = ns.GetPoints().balance, ns.MintCost(tokens)
    if balance < cost then
        return nil, ("Not enough points (%d of %d)."):format(balance, cost)
    end
    local inPot, inFire = 0, 0
    for key, n in pairs(tokens or {}) do
        if n > (ns.Tokens and ns.Tokens(key) or 0) then return nil, "You don't have those ingredients any more." end
        if ns.IngredientKind and ns.IngredientKind(key) == "fuel" then inFire = inFire + n else inPot = inPot + n end
    end
    if ns.Cauldron and inPot > ns.Cauldron().slots then return nil, "That doesn't fit in your cauldron." end
    if inFire > FIRE_SLOTS then return nil, "That's too much for the fire." end
    luck = ns.RankPerk and ns.RankPerk("luck") or 1
    plan = tokens and next(tokens) and ns.PotPlan(tokens) or nil
    local traits = RollFree(TakenPictures())
    luck, plan = 1, nil
    if not traits then return nil, "Every possible picture is already taken." end
    if tokens and ns.SpendTokens then ns.SpendTokens(tokens) end
    db.points.spent = db.points.spent + cost
    local mint = { number = ns.NextMintNumber(), traits = traits, time = time(), cost = cost, crayon = true }
    db.mints[#db.mints + 1] = mint
    ns.LearnTraits(mint.traits)  -- (your ogre can wear them now, for good)
    ns.Touch(mint)  -- syncs it to guildmates
    if ns.AddEvent then ns.AddEvent("M", mint.number) end
    if ns.CheckAchievements then ns.CheckAchievements() end
    return mint
end

-- The number for your next picture: above every number used so far, including pictures given away
-- (KillTrackerDB.removedMints), so a number never means two different pictures.
function ns.NextMintNumber()
    local db = KillTrackerDB
    local highest = 0
    for _, mint in ipairs(db.mints) do highest = math.max(highest, mint.number) end
    for number in pairs(db.removedMints or {}) do highest = math.max(highest, number) end
    return highest + 1
end

-- Gives away your picture (won in a puzzle race, see SOLC Puzzle): removes it from your pictures and your
-- showcase, and records the removal so guildmates drop it too (Sync.lua). Returns its traits, or nil.
function ns.RemoveMint(number)
    local db = KillTrackerDB
    for i, mint in ipairs(db.mints) do
        if mint.number == number then
            table.remove(db.mints, i)
            local showcase = db.showcase
            if showcase then
                for j, n in ipairs(showcase.numbers) do
                    if n == number then table.remove(showcase.numbers, j) ns.Touch(showcase) break end
                end
            end
            db.removedMints = db.removedMints or {}  -- [number] = change number of the removal
            db.seq = db.seq + 1
            db.removedMints[number] = db.seq
            if ns.OnKillsChanged then ns.OnKillsChanged() end
            return mint.traits
        end
    end
end

-- Adds a picture you won (from another player or an officer's mint battle) under your next number.
-- mintedAt: when it was first minted (kept, so it isn't taken for a later duplicate); now if new.
function ns.AddWonMint(traits, from, mintedAt)
    local db = KillTrackerDB
    local copy = {}
    for key, id in pairs(traits) do copy[key] = id end
    local mint = { number = ns.NextMintNumber(), traits = copy, time = mintedAt or time(), cost = 0, wonFrom = from }
    db.mints[#db.mints + 1] = mint
    ns.LearnTraits(mint.traits)  -- (your ogre can wear them now, for good)
    ns.Touch(mint)  -- syncs it to guildmates
    if ns.AddEvent then ns.AddEvent("W", mint.number, from) end
    if ns.CheckAchievements then ns.CheckAchievements() end
    if ns.OnKillsChanged then ns.OnKillsChanged() end
    return mint
end

-- Rolls a picture nobody in the guild owns yet, without saving it (for an officer's mint battle).
function ns.RollFreePicture()
    return RollFree(TakenPictures())
end

-- Marks your pictures that a friend minted first (earlier time; on a tie, the alphabetically first
-- name) as duplicates: mint.duplicateOf = their name. They get a free reroll.
function ns.UpdateDuplicates()
    local me = ns.MyName()
    for _, mint in ipairs(KillTrackerDB.mints) do
        mint.duplicateOf = nil
        local key = TraitKey(mint.traits)
        for fullName, friend in pairs(KillTrackerFriends or {}) do
            for _, theirs in pairs(friend.mints or {}) do
                if TraitKey(theirs.traits) == key then
                    local name = Ambiguate and Ambiguate(fullName, "short") or fullName
                    if theirs.time < mint.time or (theirs.time == mint.time and name < me) then
                        mint.duplicateOf = name
                    end
                end
            end
        end
    end
end

-- Free reroll of a duplicate: a new picture nobody has, keeping its number.
function ns.RerollMint(mint)
    if not mint.duplicateOf then return nil, "Only duplicates can be rerolled." end
    local traits = RollFree(TakenPictures(mint))
    if not traits then return nil, "Every possible picture is already taken." end
    mint.traits, mint.time, mint.duplicateOf = traits, time(), nil
    ns.LearnTraits(traits)
    ns.Touch(mint)
    return mint
end

-- Accessories are drawn in front of the hat (a weapon, a pet, a floating orb), except the ones worn on the ogre: those
-- stay under the headwear, seen only where it leaves room (a beard or long hair over a necklace, a visor over a
-- monocle). Here, not in MintArt.lua, which is generated.
local UNDER_HAT = {
    gold_chain = true, moonstone_pendant = true, gear_brd_charm = true,                     -- necklaces
    gear_ruins_charm = true, gear_zf_charm = true, gear_stratu_charm = true, gear_scholo_charm = true,  -- worn on the body
    eye_mask_pushed_up = true, monocle = true, pirate_eyepatch = true,                     -- on the face
}
ns.MINT_UNDER_HAT = UNDER_HAT
local function OverHat(layerKey, option) return layerKey == "accessory" and not UNDER_HAT[option.id] end
local FRONT_SUBLEVEL = 7  -- the top of the ARTWORK draw layer
-- The layers' sublevels, two apart from the bottom (-6, -4, ... 6), leaving room between them: a skin's front (a boss's
-- mask) goes just over the eyes, so it covers the face but not the accessory or the hat.
local function Sublevel(i) return (i - 1) * 2 - 6 end
local function SkinFrontSublevel()
    for i, layer in ipairs(ns.MintLayers) do
        if layer.key == "eyes" then return Sublevel(i) + 1 end
    end
    return FRONT_SUBLEVEL - 1
end

local function SkinLayer()
    for _, layer in ipairs(ns.MintLayers) do
        if layer.key == "skin" then return layer end
    end
    return { options = {} }
end

-- A picture's layers in drawing order, back to front: { { layer key, option id } }, with accessories over the hat
-- (OverHat) last and a skin's front (a boss's mask) right after the eyes, as RenderMint stacks them (the paint game
-- builds its colours the same way).
function ns.MintDrawOrder(traits)
    local order, front = {}, {}
    local skin = FindOption(SkinLayer(), traits.skin)
    for _, layer in ipairs(ns.MintLayers) do
        local option = FindOption(layer, traits[layer.key])
        if option then
            local list = OverHat(layer.key, option) and front or order
            list[#list + 1] = { key = layer.key, id = option.id, perSkin = option.perSkin }
        end
        if layer.key == "eyes" and skin and skin.front then  -- a skin's front, over the face (its paint grid's id)
            order[#order + 1] = { key = "skin", id = skin.id .. "_front" }
        end
    end
    for _, entry in ipairs(front) do order[#order + 1] = entry end
    return order
end

-- Draws a picture into canvas (a frame), creating one texture per layer on first use.
-- tilt (degrees clockwise, optional): the whole picture turned round its centre, as on the new Overview's tilted
-- polaroids (each layer turned and moved round the centre with it). style: which layers in crayon (ns.MintStyle).
-- Puts a layer's texture where its rect (fractions of the picture; nil: the whole picture) says, the picture turned
-- by angle (radians, clockwise) round its centre.
local function Place(tex, canvas, rect, angle)
    local size = canvas:GetWidth()
    if rect and angle ~= 0 then
        -- Its centre from the canvas's centre (y up), turned clockwise by the tilt.
        local cos, sin = math.cos(angle), math.sin(angle)
        local dx, dy = (rect[1] + rect[3] / 2 - 0.5) * size, (0.5 - rect[2] - rect[4] / 2) * size
        tex:SetPoint("CENTER", canvas, "CENTER", dx * cos + dy * sin, dy * cos - dx * sin)
        tex:SetSize(rect[3] * size, rect[4] * size)
    elseif rect then
        tex:SetPoint("TOPLEFT", canvas, "TOPLEFT", rect[1] * size, -rect[2] * size)
        tex:SetSize(rect[3] * size, rect[4] * size)
    else
        tex:SetAllPoints(canvas)
    end
    tex:SetRotation(-angle)  -- WoW turns anticlockwise
end

-- One piece on its own (an unlock in the feed, a chest's card): whole and centred, as big as fits frame, keeping its
-- shape (a hat as itself, not where it sits on an ogre). Drawn in your ogre's skin if it's one drawn per skin; a boss
-- skin with its mask. A picture drawn on the frame before hides (and ns.RenderMint hides this).
function ns.DrawPiece(frame, layerKey, option)
    for _, tex in ipairs(frame.layers or {}) do tex:Hide() end
    if frame.front then frame.front:Hide() end
    if frame.outfitFront then frame.outfitFront:Hide() end
    if frame.outfitBack then frame.outfitBack:Hide() end
    frame.drawnTraits = nil  -- (ns.DrawMint draws it afresh next time)
    frame.piece = frame.piece or frame:CreateTexture(nil, "ARTWORK", nil, 5)
    frame.pieceFront = frame.pieceFront or frame:CreateTexture(nil, "ARTWORK", nil, 6)
    local tex, front = frame.piece, frame.pieceFront
    local size = math.min(frame:GetWidth(), frame:GetHeight())
    local rect = option.rect
    local aspect = rect and rect[3] / rect[4] or 1
    tex:ClearAllPoints()
    tex:SetPoint("CENTER")
    tex:SetSize(aspect >= 1 and size or size * aspect, aspect >= 1 and size / aspect or size)
    tex:SetRotation(0)
    tex:SetVertexColor(1, 1, 1)
    local texture = option.texture and ns.MintTexture(option, ns.BaseTraits and ns.BaseTraits() or {})
    if texture then
        tex:SetTexture(texture)
        if option.color then tex:SetVertexColor(unpack(option.color)) end
    elseif option.color then
        tex:SetColorTexture(unpack(option.color))
    end
    tex:Show()
    front:SetShown(layerKey == "skin" and option.front ~= nil)
    if layerKey == "skin" and option.front then  -- (a skin fills the square: its mask where it sits on it)
        local fr = option.frontRect
        front:ClearAllPoints()
        if fr then
            front:SetPoint("TOPLEFT", tex, "TOPLEFT", fr[1] * size, -fr[2] * size)
            front:SetSize(fr[3] * size, fr[4] * size)
        else
            front:SetAllPoints(tex)
        end
        front:SetTexture(option.front)
    end
end

-- A creature's hat and onesie worn together (make-unlock-art.js's creatures): drawn as one hooded onesie, the outfit's
-- suit (its hood up where the hat goes, over the face like a hat, the face showing through), in place of both; the
-- picture keeps the two pieces. The outfit option, or nil.
local function Suit(traits)
    for _, layer in ipairs(ns.MintLayers) do
        if layer.key == "outfit" then
            local option = FindOption(layer, traits.outfit)
            if option and option.suit and option.suitHead == traits.headwear then return option end
        end
    end
end
ns.MintSuit = Suit

function ns.RenderMint(canvas, traits, tilt, style)
    canvas.layers = canvas.layers or {}
    if canvas.piece then canvas.piece:Hide() canvas.pieceFront:Hide() end  -- (a piece drawn here before, ns.DrawPiece)
    local angle = math.rad(tilt or 0)
    local covered = ns.CoveredLayers(traits)
    local suit = Suit(traits)
    -- Where the pieces worn hide the ogre (an ear through a hood, painted in tools/item-fitter.js): their masks on its
    -- skin, the suit's own when a hat and onesie are worn as one. A mask taken off a texture again can stay on it in
    -- this client (the ogre's head stayed cut after its hat went), so when they change the skin gets a fresh texture.
    local hides = {}
    if suit then
        hides[1] = suit.suitHide
    else
        for _, layer in ipairs(ns.MintLayers) do
            local option = not covered[layer.key] and FindOption(layer, traits[layer.key])
            if option and option.hide then hides[#hides + 1] = option.hide end
        end
    end
    local hideKey = table.concat(hides, "|")
    if (canvas.hideKey or "") ~= hideKey then
        for i, layer in ipairs(ns.MintLayers) do
            if layer.key == "skin" and canvas.layers[i] then
                canvas.layers[i]:Hide()
                canvas.layers[i] = nil  -- (made again below, with none)
            end
        end
        canvas.hideKey, canvas.hideMasks = hideKey, nil
    end
    for i, layer in ipairs(ns.MintLayers) do
        local tex = canvas.layers[i]
        if not tex then
            tex = canvas:CreateTexture(nil, "ARTWORK", nil, Sublevel(i))  -- sublevel = stacking order
            canvas.layers[i] = tex
        end
        local option = FindOption(layer, traits[layer.key])
        if covered[layer.key] then option = nil end  -- (under a mask: not drawn)
        if suit and layer.key == "outfit" then option = nil end  -- (the suit, in the hat's place)
        local suitHere = suit and layer.key == "headwear" and option
        local edition = not suitHere and ns.LayerEdition(style, layer.key)
        if edition and option and not option[edition] then edition = nil end  -- no twin: painted
        local texture = suitHere and suit.suit or option and option.texture and ns.MintTexture(option, traits, edition)
        tex:SetDrawLayer("ARTWORK", option and OverHat(layer.key, option) and FRONT_SUBLEVEL or Sublevel(i))
        tex:ClearAllPoints()
        tex:SetVertexColor(1, 1, 1)
        if not option or (not texture and not option.color) then
            tex:Hide()
        else
            local rect = option.rect
            if edition then rect = option[edition .. "Rect"] end  -- its own crop (none: the whole picture)
            if suitHere then rect = suit.suitRect end
            Place(tex, canvas, rect, angle)
            if texture then
                tex:SetTexture(texture)
                if option.color then tex:SetVertexColor(unpack(option.color)) end
            else
                tex:SetColorTexture(unpack(option.color))
            end
            tex:Show()
        end
    end
    -- (the masks: put on the fresh skin once; after that only placed again, the picture may be turned another way)
    if not canvas.hideMasks then
        canvas.hideMasks = {}
        local skinTex
        for i, layer in ipairs(ns.MintLayers) do
            if layer.key == "skin" then skinTex = canvas.layers[i] end
        end
        for _, file in ipairs(skinTex and hides or {}) do
            local mask = canvas:CreateMaskTexture()
            mask:SetTexture(file, "CLAMPTOBLACKADDITIVE", "CLAMPTOBLACKADDITIVE")
            skinTex:AddMaskTexture(mask)
            canvas.hideMasks[#canvas.hideMasks + 1] = mask
        end
    end
    for _, mask in ipairs(canvas.hideMasks) do
        mask:ClearAllPoints()
        Place(mask, canvas, nil, angle)
    end
    -- A skin's front (a boss's mask, option.front): over the face, under the accessory and the hat.
    local skin
    for _, layer in ipairs(ns.MintLayers) do
        if layer.key == "skin" then skin = FindOption(layer, traits.skin) end
    end
    if skin and skin.front then
        canvas.front = canvas.front or canvas:CreateTexture(nil, "ARTWORK", nil, SkinFrontSublevel())
        canvas.front:ClearAllPoints()
        Place(canvas.front, canvas, skin.frontRect, angle)
        canvas.front:SetTexture(skin.front)
        canvas.front:Show()
    elseif canvas.front then
        canvas.front:Hide()
    end
    -- An outfit's back (option.back: what's above the back line, a high collar's top, wings: make-unlock-art.js): behind
    -- the ogre, between the background and the skin, so the head covers it.
    local outfit
    for _, layer in ipairs(ns.MintLayers) do
        if layer.key == "outfit" then outfit = FindOption(layer, traits.outfit) end
    end
    if suit then outfit = nil end  -- (the suit has no parts behind or in front)
    if outfit and outfit.back then
        canvas.outfitBack = canvas.outfitBack or canvas:CreateTexture(nil, "ARTWORK", nil, Sublevel(1) + 1)
        canvas.outfitBack:ClearAllPoints()
        Place(canvas.outfitBack, canvas, outfit.backRect, angle)
        canvas.outfitBack:SetTexture(outfit.back)
        canvas.outfitBack:Show()
    elseif canvas.outfitBack then
        canvas.outfitBack:Hide()
    end
    -- An outfit's front (option.front: its parts in front of the face): over the expression and the eyes.
    if outfit and outfit.front then
        canvas.outfitFront = canvas.outfitFront or canvas:CreateTexture(nil, "ARTWORK", nil, SkinFrontSublevel())
        canvas.outfitFront:ClearAllPoints()
        Place(canvas.outfitFront, canvas, outfit.frontRect, angle)
        canvas.outfitFront:SetTexture(outfit.front)
        canvas.outfitFront:Show()
    elseif canvas.outfitFront then
        canvas.outfitFront:Hide()
    end
end

-- Pictures whose traits no longer exist (e.g. from the placeholder test set) are removed and refunded.
-- A picture missing a layer added later isn't outdated; it simply has nothing on that layer.
local function RemoveOutdatedMints()
    local db, kept, refund, removed = KillTrackerDB, {}, 0, 0
    for _, mint in ipairs(db.mints) do
        if not mint.wonFrom and mint.crayon == nil then mint.crayon = true end  -- minted before the crayon edition
    end
    for _, mint in ipairs(db.mints) do
        local valid = true
        for _, layer in ipairs(ns.MintLayers) do
            local id = mint.traits[layer.key]
            if id and not FindOption(layer, id) then valid = false end
        end
        if valid then
            kept[#kept + 1] = mint
            if mint.number ~= #kept then mint.number = #kept; ns.Touch(mint) end
        else
            refund = refund + (mint.cost or 100)  -- pictures from before 0.32.0 all cost 100
            removed = removed + 1
        end
    end
    if refund > 0 then
        db.mints = kept
        db.points.spent = math.max(0, db.points.spent - refund)
        ns.Print(("Removed %d test picture(s) made with the old placeholder art; %d points refunded."):format(removed, refund))
    end
end

local loader = CreateFrame("Frame")
loader:RegisterEvent("PLAYER_LOGIN")
loader:SetScript("OnEvent", RemoveOutdatedMints)

StaticPopupDialogs["SOLC_REROLL"] = {
    text = "%s minted this picture first. Reroll it for free?",
    button1 = YES or "Yes",
    button2 = NO or "No",
    OnAccept = function(_, mint)
        local rerolled, reason = ns.RerollMint(mint)
        if not rerolled then
            ns.Print(reason)
            return
        end
        if ns.OnKillsChanged then ns.OnKillsChanged() end
        ns.PlayMintReel(rerolled)
    end,
    timeout = 0,
    whileDead = true,
    hideOnEscape = true,
}

function ns.ConfirmReroll(mint)
    StaticPopup_Show("SOLC_REROLL", mint.duplicateOf, nil, mint)
end

StaticPopupDialogs["SOLC_MINT"] = {
    text = "Mint a new picture for %d points?",
    button1 = YES or "Yes",
    button2 = NO or "No",
    OnAccept = function() ns.DoMint() end,
    timeout = 0,
    whileDead = true,
    hideOnEscape = true,
}

-- Mints (with tokens in the pot, if any) and plays the reel (MintReel.lua: it reveals the picture layer by layer and
-- announces it). Returns the mint, or nil (and says why).
function ns.DoMint(tokens)
    local mint, reason = ns.Mint(tokens)
    if not mint then
        ns.Print(reason)
        return
    end
    if ns.OnKillsChanged then ns.OnKillsChanged() end
    ns.PlayMintReel(mint)
    return mint
end

-- Minting happens in the minting pot's kitchen (MintPot.lua); a popup asks if it isn't there.
function ns.ConfirmMint()
    if ns.ShowMintPot then
        local ok, err = pcall(ns.ShowMintPot)
        if ok then return end
        ns.Print("|cffff5555The minting pot broke:|r " .. tostring(err))  -- (say so, rather than skip it quietly)
    end
    StaticPopup_Show("SOLC_MINT", ns.MintCost())
end

-- Showcase: up to SHOWCASE_SIZE of your pictures on your Overview, synced to guildmates (Sync.lua):
-- KillTrackerDB.showcase = { numbers = { picture number, ... }, backdrop = background option id, seq }.

ns.SHOWCASE_SIZE = 3

local function Showcase()
    local db = KillTrackerDB
    db.showcase = db.showcase or { numbers = {} }
    return db.showcase
end

function ns.IsShowcased(number)
    for _, n in ipairs(Showcase().numbers) do
        if n == number then return true end
    end
    return false
end

-- Adds your picture to the showcase, or takes it off. Returns false and a reason if the showcase is full.
function ns.ToggleShowcase(mint)
    local showcase = Showcase()
    if ns.IsShowcased(mint.number) then
        for i, n in ipairs(showcase.numbers) do
            if n == mint.number then table.remove(showcase.numbers, i) break end
        end
    elseif #showcase.numbers >= ns.SHOWCASE_SIZE then
        return false, ("Your showcase is full (%d pictures). Take one off first."):format(ns.SHOWCASE_SIZE)
    else
        showcase.numbers[#showcase.numbers + 1] = mint.number
    end
    ns.Touch(showcase)
    if ns.CheckAchievements then ns.CheckAchievements() end
    if ns.OnKillsChanged then ns.OnKillsChanged() end
    return true
end

-- Your ogre: one you build yourself (KillTrackerDB.card.ogre = { [layer key] = option id }) from your wardrobe: every
-- trait you've had on a picture of yours (minted, won or rerolled; KillTrackerDB.wardrobe = { ["layer:id"] = true }),
-- kept for good, even once the picture's gone. An unlocked piece isn't in it until you mint it (it can roll now: the
-- minting pot helps); it's tried on meanwhile (ns.TryOn: an unlock in the feed, a chest's cards). Your Overview's photo
-- if you pick it (card.photoOgre).

-- Puts traits in your wardrobe.
-- Pieces made from others (an option's unlock "combine:<layer:id>+<layer:id>": Sul'thraze from its two halves): it
-- unlocks once every part is in your wardrobe (minted in a picture of yours), and rolls like any unlocked piece.
local function CheckCombines(wardrobe)
    for _, layer in ipairs(ns.MintLayers) do
        for _, option in ipairs(layer.options) do
            local parts = option.unlock and option.unlock:match("^combine:(.+)$")
            if parts and not ns.IsUnlocked(ns.OptionKey(layer.key, option)) then
                local all = true
                for part in parts:gmatch("[^+]+") do
                    if not wardrobe[part] then all = false end
                end
                if all then ns.UnlockOption(ns.OptionKey(layer.key, option)) end
            end
        end
    end
end
function ns.LearnTraits(traits)
    local wardrobe = KillTrackerDB.wardrobe or {}
    KillTrackerDB.wardrobe = wardrobe
    local new = false
    for key, id in pairs(traits or {}) do
        if not wardrobe[key .. ":" .. id] then wardrobe[key .. ":" .. id], new = true, true end
    end
    if new and ns.UnlockOption then CheckCombines(wardrobe) end
end

-- The options you can build with on a layer (your wardrobe's), rarest first.
function ns.OwnedOptions(layerKey)
    local layer
    for _, l in ipairs(ns.MintLayers) do if l.key == layerKey then layer = l end end
    if not layer then return {} end
    for _, mint in ipairs(KillTrackerDB.mints or {}) do ns.LearnTraits(mint.traits) end  -- (the pictures from before it)
    local wardrobe = KillTrackerDB.wardrobe
    local list = {}
    for _, option in ipairs(layer.options) do
        if wardrobe[layer.key .. ":" .. option.id] then list[#list + 1] = option end
    end
    table.sort(list, function(a, b)
        if RARITY_SCORE[a.rarity] ~= RARITY_SCORE[b.rarity] then return RARITY_SCORE[a.rarity] > RARITY_SCORE[b.rarity] end
        return a.name < b.name
    end)
    return list
end
-- The everyday ogre: each layer's first ordinary option.
local function PlainTraits()
    local traits = {}
    for _, layer in ipairs(ns.MintLayers) do
        for _, option in ipairs(layer.options) do
            if not option.unlock and not option.retired then traits[layer.key] = option.id break end
        end
    end
    return traits
end
-- The ogre pieces are tried on: yours (built), else your photo's picture's, else the everyday one. A copy.
function ns.BaseTraits()
    local card = KillTrackerDB.card
    local mint = card and card.portrait and ns.FindMint(nil, card.portrait)
    local from = card and card.ogre or (mint and mint.traits) or PlainTraits()
    local traits = {}
    for key, id in pairs(from) do traits[key] = id end
    return traits
end
-- A piece on your ogre: its traits with that layer's swapped for it.
function ns.TryOn(layerKey, id)
    local traits = ns.BaseTraits()
    traits[layerKey] = id
    return traits
end
-- The edition after this one that a piece has (painted, crayon, sketch, painted...: only the ones drawn for it).
function ns.NextEditionFor(option, edition)
    local order = { false }
    for _, e in ipairs(ns.EDITIONS) do if option[e] then order[#order + 1] = e end end
    for i, e in ipairs(order) do
        if e == (edition or false) then return order[i % #order + 1] or nil end
    end
    return nil
end
-- Your ogre's layers in crayon or sketched (card.ogreStyle = { [layer key] = edition }; painted: not in it).
function ns.SetOgreEdition(layerKey, edition)
    KillTrackerDB.card = KillTrackerDB.card or {}
    local card = KillTrackerDB.card
    card.ogreStyle = card.ogreStyle or {}
    card.ogreStyle[layerKey] = edition or nil
    if not next(card.ogreStyle) then card.ogreStyle = nil end
    ns.Touch(card)
    if ns.OnKillsChanged then ns.OnKillsChanged() end
end
-- Saves your ogre (traits), and makes it your Overview's photo or not (asPhoto: nil leaves that as it is).
function ns.SetOgre(traits, asPhoto)
    KillTrackerDB.card = KillTrackerDB.card or {}
    local card = KillTrackerDB.card
    card.ogre = {}
    for key, id in pairs(traits) do card.ogre[key] = id end
    if asPhoto ~= nil then
        card.photoOgre = asPhoto or nil
        if asPhoto then card.portrait = nil end
    end
    ns.Touch(card)
    if ns.OnKillsChanged then ns.OnKillsChanged() end
end

-- Sets your whole showcase at once (the Overview's gallery: dragged in, swapped, taken off): numbers in their slots'
-- order, your own pictures only, each once, at most SHOWCASE_SIZE.
function ns.SetShowcase(numbers)
    local showcase, list, seen = Showcase(), {}, {}
    for _, number in ipairs(numbers) do
        if #list < ns.SHOWCASE_SIZE and not seen[number] and ns.FindMint(nil, number) then
            list[#list + 1], seen[number] = number, true
        end
    end
    showcase.numbers = list
    ns.Touch(showcase)
    if ns.CheckAchievements then ns.CheckAchievements() end
    if ns.OnKillsChanged then ns.OnKillsChanged() end
end

-- The background behind your 3D model on the Overview: one from a picture you own, chosen by right-clicking
-- the model; showcase.backdrop = its option id, synced with the showcase.

-- The backgrounds on your pictures, each once, as options (id, name, rarity, texture), rarest first.
function ns.OwnedBackgrounds()
    local layer
    for _, l in ipairs(ns.MintLayers) do
        if l.key == "background" then layer = l end
    end
    local seen, list = {}, {}
    for _, mint in ipairs(layer and KillTrackerDB.mints or {}) do
        local id = mint.traits and mint.traits.background
        local option = id and not seen[id] and FindOption(layer, id)
        if option then
            seen[id] = true
            list[#list + 1] = option
        end
    end
    table.sort(list, function(a, b)
        if a.rarity ~= b.rarity then return (RARITY_SCORE[a.rarity] or 0) > (RARITY_SCORE[b.rarity] or 0) end
        return a.name < b.name
    end)
    return list
end

-- Sets (option id) or clears (nil) the background behind your model.
function ns.SetModelBackdrop(id)
    local showcase = Showcase()
    if showcase.backdrop == id then return end
    showcase.backdrop = id
    ns.Touch(showcase)
    if ns.OnKillsChanged then ns.OnKillsChanged() end
end

-- The background behind someone's model, as an option: yours (key nil; only while you still own a picture with
-- it) or a synced guildmate's. nil for none.
function ns.GetModelBackdrop(key)
    local source = key and KillTrackerFriends[key] or KillTrackerDB
    return ns.BackgroundOption(key, source and source.showcase and source.showcase.backdrop)
end

-- A background option by its id for someone: yours (key nil; only while you still own a picture with it) or a
-- synced guildmate's. nil for none.
function ns.BackgroundOption(key, id)
    if not id then return nil end
    if key then
        for _, l in ipairs(ns.MintLayers) do
            if l.key == "background" then return FindOption(l, id) end
        end
        return nil
    end
    for _, option in ipairs(ns.OwnedBackgrounds()) do
        if option.id == id then return option end
    end
end

-- Someone's showcased pictures, in order: yours (key nil) or a synced guildmate's. Pictures that no
-- longer exist are skipped.
-- Someone's picture by its number: yours (key nil) or a synced guildmate's; nil if they don't have it (any more).
function ns.FindMint(key, number)
    local source = key and KillTrackerFriends[key] or KillTrackerDB
    if not source or not number then return end
    if key then return source.mints and source.mints[number] end
    for _, mint in ipairs(source.mints or {}) do
        if mint.number == number then return mint end
    end
end

-- Someone's newest picture (the highest number they own), or nil if they have none.
function ns.NewestMint(key)
    local source = key and KillTrackerFriends[key] or KillTrackerDB
    local newest
    for _, mint in pairs(source and source.mints or {}) do
        if not newest or mint.number > newest.number then newest = mint end
    end
    return newest
end

function ns.GetShowcase(key)
    local source = key and KillTrackerFriends[key] or KillTrackerDB
    local numbers = source and source.showcase and source.showcase.numbers or {}
    local pictures = {}
    for _, number in ipairs(numbers) do
        local mint = ns.FindMint(key, number)
        if mint then pictures[#pictures + 1] = mint end
    end
    return pictures
end
